import unittest
from treasure_hunter import Game

class TestGame(unittest.TestCase):

    def setUp(self):
        self.game = Game()

    def test_initial_state(self):
        self.assertEqual(self.game.current_room, 'hallway')
        self.assertEqual(self.game.health, 100)
        self.assertEqual(self.game.inventory, [])

    def test_move_north(self):
        self.game.move('north')
        self.assertEqual(self.game.current_room, 'garden')

    def test_move_south(self):
        self.game.current_room = 'garden'
        self.game.move('south')
        self.assertEqual(self.game.current_room, 'hallway')

    def test_collect_treasure(self):
        self.game.collect_treasure('treasure')
        self.assertIn('treasure', self.game.inventory)

    def test_health_system(self):
        self.game.take_damage(50)
        self.assertEqual(self.game.health, 50)

    def test_win_condition(self):
        # Simulate collecting all treasures
        self.game.inventory = ['treasure1', 'treasure2', 'treasure3']
        self.assertTrue(self.game.has_won())

    def test_move_invalid_direction(self):
        with self.assertRaises(ValueError):
            self.game.move('invalid_direction

